const money=n=>'৳'+n.toLocaleString('en-BD');
const main=document.getElementById('main');
let cart=[];try{cart=JSON.parse(sessionStorage.getItem('aura-bag')||'[]').filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20)}catch{};
let category='All',brand='All',query='',sort='featured';
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(p){return `<article class="product"><a href="#product/${p.id}" aria-label="View ${p.name}"><div class="product-image"><span class="tag">${p.tag}</span><img src="assets/${p.image}" alt="${p.name}" loading="lazy" width="240" height="240"></div><div class="product-copy"><span class="product-brand">${p.brand}</span><h3>${p.name}</h3><div class="product-meta">${p.variant}</div><div class="swatches" aria-hidden="true">${p.colors.map(c=>`<span class="swatch" style="background:${c}"></span>`).join('')}</div><div class="product-bottom"><span>${money(p.price)}</span><span class="round-link" aria-hidden="true">↗</span></div></div></a></article>`}
function oldHome(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">Thoughtfully chosen. Everyday extraordinary.</div><h1>A little<br>ahead<span> of<br>the everyday.</span></h1><p>Discover phones and accessories that make the everyday feel exceptional.</p><a class="btn" href="#catalog/Phones">Explore phones <span>↗</span></a></div><div class="hero-visual"><img src="assets/iphone.png" alt="iPhone 16 Pro in four titanium finishes" fetchpriority="high"><a class="hero-note" href="#product/iphone-16-pro"><div>iPhone 16 Pro<span>Titanium. Beautifully capable.</span></div><b>↗</b></a><span class="hero-number">01 / KNOTWORK EDIT</span></div></section><div class="benefits"><span><b>◇</b> Apple, Samsung & Google</span><span><b>⌁</b> Phones to everyday essentials</span><span><b>৳</b> Prices in Bangladeshi taka</span><span><b>↗</b> Find your next favourite</span></div><section class="section"><div class="section-heading"><div><h2>The considered collection.</h2><p>Standout tech. A place in your everyday.</p></div><a class="text-link" href="#catalog/All">Shop the collection ↗</a></div><div class="categories">${['All','Phones','Audio','Charging','Cases'].map(c=>`<a class="chip ${c==='All'?'active':''}" href="#catalog/${c}">${c==='All'?'All products':c}</a>`).join('')}</div><div class="grid">${products.slice(0,4).map(card).join('')}</div></section><section class="section feature"><div><div class="eyebrow">Turn down the world</div><h2>Small essentials.<br>Big difference.</h2><p>A soundtrack for the commute.<br>A little quiet when you need it.</p><a class="text-link" href="#catalog/Audio">Explore audio ↗</a></div><img src="assets/airpods.png" alt="AirPods Pro 2 and charging case" loading="lazy"></section>`}
function catalogue(cat){category=['All','Phones','Audio','Charging','Cases'].includes(cat)?cat:'All';main.innerHTML=`<section class="section"><div class="section-heading"><div><div class="eyebrow">The Knotwork Globe Limited collection</div><h2 id="catalogTitle">${category==='All'?'Find your next favourite.':category+'. Considered.'}</h2><p>Explore our sample collection. All prices are illustrative.</p></div></div><div class="categories">${['All','Phones','Audio','Charging','Cases'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}">${c==='All'?'All products':c}</button>`).join('')}</div><div class="catalog-top"><input id="search" class="search" type="search" placeholder="Search phones, accessories, brands…" aria-label="Search products" value="${escapeHtml(query)}"><select id="brand" aria-label="Filter by brand">${['All','Apple','Samsung','Google','Nothing'].map(b=>`<option ${b===brand?'selected':''} value="${b}">${b==='All'?'All brands':b}</option>`).join('')}</select><select id="sort" aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></div><p id="resultsCount" class="demo-note" aria-live="polite"></p><div class="grid" id="results"></div></section>`;document.getElementById('sort').value=sort;document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{location.hash='catalog/'+b.dataset.category});document.getElementById('search').oninput=e=>{query=e.target.value;renderResults()};document.getElementById('brand').onchange=e=>{brand=e.target.value;renderResults()};document.getElementById('sort').onchange=e=>{sort=e.target.value;renderResults()};renderResults()}
function filtered(){let list=products.filter(p=>(category==='All'||p.category===category)&&(brand==='All'||p.brand===brand)&&`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(query.toLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);return list}
function renderResults(){let list=filtered();document.getElementById('resultsCount').textContent=`${list.length} product${list.length===1?'':'s'}`;document.getElementById('results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>No products found.</h3><p>Try a different search or reset your filters.</p><button class="btn secondary" id="reset">Reset filters</button></div>';const reset=document.getElementById('reset');if(reset)reset.onclick=()=>{brand='All';query='';sort='featured';catalogue('All')}}
function oldDetail(id){let p=products.find(p=>p.id===id);if(!p){main.innerHTML='<section class="section empty"><h1>Product not found</h1><a href="#catalog/All">Return to the collection</a></section>';return}main.innerHTML=`<section class="section"><a class="back" href="#catalog/${p.category}">← Back to ${p.category.toLowerCase()}</a><div class="detail"><div class="detail-image"><img src="assets/${p.image}" alt="${p.name}"></div><div><div class="eyebrow">${p.brand} / ${p.category}</div><h1>${p.name}</h1><p>${p.description}</p><div class="price">${money(p.price)}</div><div class="option-label">Selected configuration</div><div class="chip" style="display:inline-block">${p.variant}</div><p class="demo-note">Sample product and price. Availability and final pricing will be confirmed when the store launches.</p><button class="btn full" id="addToBag">Add to bag <span>+</span></button><div class="specs">${Object.entries(p.specs).map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div></div></div></section>`;document.getElementById('addToBag').onclick=()=>add(p.id)}
function saveCart(){try{sessionStorage.setItem('aura-bag',JSON.stringify(cart))}catch{}document.getElementById('bagCount').textContent=cart.reduce((s,x)=>s+x.qty,0)}
function oldAdd(id){const p=products.find(x=>x.id===id);if(!p)throw Error('Unknown product');let item=cart.find(x=>x.id===id);if(item&&item.qty>=20){toast('Maximum 20 of each item');return}if(item)item.qty++;else cart.push({id,qty:1});saveCart();toast(p.name+' added to bag')}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
const subtotal=()=>cart.reduce((s,x)=>s+(x.price||products.find(p=>p.id===x.id).price)*x.qty,0);
function renderBag(){const body=document.getElementById('bagContent');body.innerHTML=cart.length?`${cart.map(x=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-row"><img src="assets/${x.image||p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${escapeHtml(x.variant||p.variant)}</p><div class="quantity"><button data-quantity="-1" data-id="${x.key||p.id}" aria-label="Decrease ${p.name} quantity">−</button><span>${x.qty}</span><button data-quantity="1" data-id="${x.key||p.id}" aria-label="Increase ${p.name} quantity">+</button></div></div><div>${money(x.qty*(x.price||p.price))}<br><button class="remove" data-remove="${x.key||p.id}">Remove</button></div></div>`}).join('')}<div class="total-row"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><p class="demo-note">Demo bag. Delivery is calculated at checkout.</p><button class="btn full" id="checkoutButton">Continue to demo checkout ↗</button>`:'<div class="empty"><h3>A little room for something good.</h3><p>Your bag is empty.</p><button class="btn" id="browseBag">Explore the collection</button></div>';body.querySelectorAll('[data-quantity]').forEach(b=>b.onclick=()=>{let x=cart.find(x=>(x.key||x.id)===b.dataset.id);x.qty=Math.min(20,x.qty+Number(b.dataset.quantity));cart=cart.filter(x=>x.qty>0);saveCart();renderBag()});body.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(x=>(x.key||x.id)!==b.dataset.remove);saveCart();renderBag()});const checkout=document.getElementById('checkoutButton');if(checkout)checkout.onclick=()=>{document.getElementById('bagDialog').close();location.hash='checkout'};const browse=document.getElementById('browseBag');if(browse)browse.onclick=()=>{document.getElementById('bagDialog').close();location.hash='catalog/All'}}
function checkout(){if(!cart.length){main.innerHTML='<section class="section empty"><h1>Your bag is empty.</h1><a class="btn" href="#catalog/All">Explore the collection</a></section>';return}main.innerHTML=`<section class="section checkout"><a class="back" href="#catalog/All">← Continue shopping</a><div class="eyebrow">One last step</div><h1>Demo checkout</h1><p class="demo-note">Try the checkout with sample details. No order is sent, no payment is taken, and these details are not saved.</p><form id="checkoutForm"><label class="field">Full name<input name="name" placeholder="Sample customer" autocomplete="off" required maxlength="80"></label><label class="field">Bangladesh phone number<input name="phone" type="tel" placeholder="01XXXXXXXXX" pattern="(\+?88)?01[3-9][0-9]{8}" title="Use a Bangladesh mobile number, e.g. 01712345678" required autocomplete="off"></label><label class="field">Delivery address<textarea name="address" placeholder="House, road, area" required minlength="8" maxlength="300" autocomplete="off"></textarea></label><label class="field">Delivery area<select id="deliveryArea"><option value="80">Inside Dhaka — ৳80</option><option value="150">Outside Dhaka — ৳150</option></select></label><label class="field">Payment method<select><option>Cash on delivery (demo)</option></select></label><div class="total-row"><span>Products</span><strong>${money(subtotal())}</strong></div><div class="total-row"><span>Delivery · illustrative</span><strong id="deliveryCost">৳80</strong></div><div class="total-row"><span>Total</span><strong id="checkoutTotal">${money(subtotal()+80)}</strong></div><button class="btn full" type="submit">Complete demo checkout ↗</button></form></section>`;document.getElementById('deliveryArea').onchange=e=>{document.getElementById('deliveryCost').textContent=money(+e.target.value);document.getElementById('checkoutTotal').textContent=money(subtotal()+ +e.target.value)};document.getElementById('checkoutForm').onsubmit=e=>{e.preventDefault();cart=[];saveCart();main.innerHTML='<section class="section success"><div class="eyebrow">Thank you for trying Knotwork Globe Limited</div><h1>That’s the full experience.</h1><p>Your demo checkout is complete. No real order was placed.</p><a class="btn" href="#catalog/All">Back to the collection ↗</a></section>';window.scrollTo(0,0)}}
function renderRoute(){disposeStorefront();let [page,arg]=(location.hash.slice(1)||'home').split('/');document.body.classList.toggle('is-home',!['catalog','product','checkout'].includes(page));document.querySelector('nav').classList.remove('open');document.getElementById('menuButton').setAttribute('aria-expanded','false');if(page==='catalog')catalogue(arg);else if(page==='product')detail(arg);else if(page==='checkout')checkout();else home();document.title=page==='product'?(products.find(p=>p.id===arg)?.name||'Product')+' — Knotwork Globe Limited':'Knotwork Globe Limited — Good tech. Great feeling.';window.scrollTo({top:0,behavior:'instant'});main.classList.remove('route-enter');void main.offsetWidth;main.classList.add('route-enter')}

let selectedId='iphone-18-pro-max', colorIndex=2, storageIndex=0, effect='fluid', speed=45, paused=false;
const phoneProducts=()=>products.filter(p=>p.category==='Phones');
function selected(){return products.find(p=>p.id===selectedId)||phoneProducts()[0]}
function finish(p=selected()){return p.finishes?.[colorIndex]||{name:p.variant.split(' · ').pop(),hex:p.colors[0],image:p.image}}
function capacity(p=selected()){return (p.storage||['256GB'])[storageIndex]||p.storage[0]}
function configuredPrice(p=selected()){return p.price+storageIndex*18000}
function home(){renderStorefront()}
function detail(id){const p=products.find(p=>p.id===id);if(!p||p.category!=='Phones'){oldDetail(id);return}if(selectedId!==id){selectedId=id;colorIndex=0;storageIndex=0}studio()}
function studio(){const p=selected(), f=finish(p);main.innerHTML=`<section class="studio" id="studio" data-effect="${effect}"><div class="ambient" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="studio-top"><span><a href="#catalog/Phones" class="studio-back">← All phones</a>THE COLOUR STUDIO <span class="divider">/</span> 01</span><button id="fullscreen" class="quiet">⛶ <span>Full view</span></button></div><div class="showcase"><div class="showcase-copy"><div class="eyebrow">${p.brand} / THE COLLECTION</div><h1>Find your<br><em>colour.</em></h1><p>A phone that feels like you.</p></div><div class="phone-stage"><span class="ghost-brand" aria-hidden="true">${p.brand==='Apple'?'iPhone':p.brand==='Samsung'?'Galaxy':p.brand==='Google'?'Pixel':'Nothing'}</span><img id="heroPhone" src="assets/${f.image||p.image}" alt="${p.name} in ${f.name}" fetchpriority="high"><div class="phone-caption"><span id="captionFinish">${f.name}</span><span>${p.name}</span></div></div></div><aside class="config glass"><div class="panel-heading"><span>Make it yours</span><span class="tiny-icon">◈</span></div><label class="label" for="modelSelect">01 <span>MODEL</span></label><select id="modelSelect">${['Apple','Samsung','Google','Nothing'].map(b=>`<optgroup label="${b}">${phoneProducts().filter(x=>x.brand===b).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.name}</option>`).join('')}</optgroup>`).join('')}</select><div class="label">02 <span>COLOUR</span><b id="finishName">${f.name}</b></div><div class="color-options" role="group" aria-label="Phone colour">${(p.finishes||[]).map((c,i)=>`<button class="color-choice ${i===colorIndex?'selected':''}" style="--swatch:${c.hex}" data-color="${i}" aria-label="${c.name}" aria-pressed="${i===colorIndex}" title="${c.name}"><span></span></button>`).join('')}</div><div class="label">03 <span>STORAGE</span></div><div class="storage-options" role="group" aria-label="Phone storage">${(p.storage||['256GB']).map((s,i)=>`<button data-storage="${i}" class="${i===storageIndex?'selected':''}" aria-pressed="${i===storageIndex}">${s}</button>`).join('')}</div><div class="config-price"><div><small>DEMO PRICE</small><strong id="configPrice">${money(configuredPrice(p))}</strong></div><span class="price-note">${p.releaseNote||'Sample pricing'}</span></div><button class="btn full" id="addConfigured">Add to bag <span>↗</span></button><div class="scene-controls"><div class="label"><span>SET THE MOOD</span><button class="quiet" id="resetScene">Reset</button></div><div class="effect-options" aria-label="Background effect">${['fluid','aurora','glow'].map(x=>`<button data-effect-choice="${x}" class="${effect===x?'selected':''}">${x==='fluid'?'≈':x==='aurora'?'⌁':'◌'} ${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="motion-row"><label for="speed">Motion</label><input id="speed" type="range" min="0" max="100" value="${speed}"><button id="pauseMotion" class="quiet" aria-label="${paused?'Play':'Pause'} background animation">${paused?'▶':'Ⅱ'}</button></div></div></aside><div class="studio-bottom"><span>YOUR PHONE. YOUR FINISH.</span><button class="quiet" id="surprise">✧ Surprise me</button><a href="#collection" id="exploreBelow">Explore the collection ↓</a></div></section><section class="section collection" id="collection"><div class="section-heading"><div class="eyebrow">CURATED FOR YOUR EVERYDAY</div><h2>Different by choice.</h2><p>Your favourite brands. Every detail considered.</p></div><div class="collection-toolbar"><div class="brand-tabs">${['All','Apple','Samsung','Google','Nothing'].map(b=>`<button class="chip ${b==='All'?'active':''}" data-home-brand="${b}">${b==='All'?'All phones':b}</button>`).join('')}</div><a href="#catalog/All" class="text-link">View all products ↗</a></div><div class="grid" id="homeGrid">${phoneProducts().map(card).join('')}</div></section><section class="accessory-strip section"><div><div class="eyebrow">THE FINISHING TOUCHES</div><h2>Better together.</h2><a href="#catalog/Audio" class="text-link">Explore accessories ↗</a></div><a href="#product/airpods-pro"><img src="assets/airpods.png" alt="AirPods Pro 2"><span>AirPods Pro 2 ↗</span></a><a href="#product/usb-c-charger"><img src="assets/charger.jpg" alt="20W USB-C adapter"><span>Power, wherever you go ↗</span></a></section>`;
applyAtmosphere();document.getElementById('modelSelect').onchange=e=>{selectedId=e.target.value;colorIndex=0;storageIndex=0;history.replaceState(null,'','#product/'+selectedId);document.title=selected().name+' — Knotwork Globe Limited';studio()};document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{colorIndex=+b.dataset.color;updateConfiguration()});document.querySelectorAll('[data-storage]').forEach(b=>b.onclick=()=>{storageIndex=+b.dataset.storage;updateConfiguration()});document.getElementById('addConfigured').onclick=()=>add(p.id);document.querySelectorAll('[data-effect-choice]').forEach(b=>b.onclick=()=>{effect=b.dataset.effectChoice;applyAtmosphere()});document.getElementById('speed').oninput=e=>{speed=+e.target.value;applyAtmosphere()};document.getElementById('pauseMotion').onclick=()=>{paused=!paused;applyAtmosphere()};document.getElementById('resetScene').onclick=()=>{effect='fluid';speed=45;paused=false;document.getElementById('speed').value=speed;applyAtmosphere()};document.getElementById('surprise').onclick=()=>{colorIndex=Math.floor(Math.random()*p.finishes.length);effect=['fluid','aurora','glow'][Math.floor(Math.random()*3)];updateConfiguration()};document.getElementById('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.getElementById('studio').requestFullscreen)await document.getElementById('studio').requestFullscreen();else document.getElementById('studio').classList.toggle('expanded')}catch{toast('Full view is not supported in this browser')}};document.getElementById('exploreBelow').onclick=e=>{e.preventDefault();document.getElementById('collection').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-home-brand]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-home-brand]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('homeGrid').innerHTML=phoneProducts().filter(x=>b.dataset.homeBrand==='All'||x.brand===b.dataset.homeBrand).map(card).join('')})}
function updateConfiguration(){const p=selected(),f=finish(p),im=document.getElementById('heroPhone');im.src='assets/'+(f.image||p.image);im.alt=p.name+' in '+f.name;if(!reduceMotion())im.animate?.([{opacity:.25,transform:'translateY(10px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:430,easing:'ease-out'});document.getElementById('finishName').textContent=f.name;document.getElementById('captionFinish').textContent=f.name;document.getElementById('configPrice').textContent=money(configuredPrice());document.querySelectorAll('[data-color]').forEach(b=>{b.classList.toggle('selected',+b.dataset.color===colorIndex);b.setAttribute('aria-pressed',+b.dataset.color===colorIndex)});document.querySelectorAll('[data-storage]').forEach(b=>{b.classList.toggle('selected',+b.dataset.storage===storageIndex);b.setAttribute('aria-pressed',+b.dataset.storage===storageIndex)});applyAtmosphere()}
function applyAtmosphere(){const s=document.getElementById('studio');if(!s)return;s.dataset.effect=effect;s.style.setProperty('--finish',finish().hex);s.style.setProperty('--duration',(45-speed*.35)+'s');s.classList.toggle('paused',paused||speed===0);document.querySelectorAll('[data-effect-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.effectChoice===effect));const b=document.getElementById('pauseMotion');b.textContent=paused?'▶':'Ⅱ';b.setAttribute('aria-label',(paused?'Play':'Pause')+' background animation')}
function add(id){const p=products.find(x=>x.id===id);if(!p)return;const isPhone=p.category==='Phones';const variant=isPhone?capacity(p)+' · '+finish(p).name:p.variant;const key=id+'|'+variant;let x=cart.find(x=>x.key===key);if(x?.qty>=20){toast('Maximum 20 of each configuration');return}if(x)x.qty++;else cart.push({id,key,variant,price:isPhone?configuredPrice(p):p.price,image:isPhone?finish(p).image:p.image,qty:1});saveCart();toast(p.name+' · '+variant+' added to bag')}

document.getElementById('bagButton').onclick=()=>{renderBag();document.getElementById('bagDialog').showModal()};document.getElementById('menuButton').onclick=e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))};document.getElementById('searchButton').onclick=()=>{if(location.hash==='#catalog/All')document.getElementById('search')?.focus();else{location.hash='catalog/All';setTimeout(()=>document.getElementById('search')?.focus(),50)}};let routeSequence=0;
function route(){const sequence=++routeSequence;const paint=()=>{if(sequence!==routeSequence)return;renderRoute();updateGlassHeader()};if(document.startViewTransition&&!reduceMotion())document.startViewTransition(paint);else paint()}
function updateGlassHeader(){const header=document.querySelector('header');const bounds=header.getBoundingClientRect();const dark=[...document.querySelectorAll('main .sf-dark')].some(el=>{const r=el.getBoundingClientRect();return r.top<bounds.top+bounds.height/2&&r.bottom>bounds.top+bounds.height/2});header.classList.toggle('over-dark',dark)}
let glassFrame=0;addEventListener('scroll',()=>{if(glassFrame)return;glassFrame=requestAnimationFrame(()=>{glassFrame=0;updateGlassHeader()})},{passive:true});addEventListener('resize',updateGlassHeader);
window.addEventListener('hashchange',route);saveCart();renderRoute();updateGlassHeader();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_knotwork_catalog',description:'Search the demo Knotwork Globe Limited catalogue and show the matching products.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.query!=='string'||input.query.length>100)throw Error('A search query of at most 100 characters is required');query=input.query;brand='All';category='All';if(location.hash!=='#catalog/All')location.hash='catalog/All';catalogue('All');return filtered().map(({id,name,price})=>({id,name,demoPriceBDT:price}))}})).catch(()=>{})}catch{}}
// Keep the mobile navigation dismissible by keyboard and outside clicks.
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('nav').classList.remove('open');document.getElementById('menuButton').setAttribute('aria-expanded','false')}});
document.addEventListener('click',e=>{if(!e.target.closest('header')){document.querySelector('nav').classList.remove('open');document.getElementById('menuButton').setAttribute('aria-expanded','false')}});
